[ORDERS 테이블 스키마 및 데이터]
CREATE TABLE ORDERS (
    ORDER_ID INT,
    ORDER_DATE DATE,
    TOTAL_AMOUNT INT
);
INSERT INTO ORDERS VALUES (1, '2023-01-01', 100);
INSERT INTO ORDERS VALUES (2, '2023-01-02', 200);
INSERT INTO ORDERS VALUES (3, '2023-01-02', 150);
INSERT INTO ORDERS VALUES (4, '2023-01-03', 300);

[SQL]
SELECT
    ORDER_ID,
    ORDER_DATE,
    TOTAL_AMOUNT,
    SUM(TOTAL_AMOUNT) OVER (ORDER BY ORDER_DATE RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS CUMULATIVE_SUM_RANGE
FROM ORDERS
ORDER BY ORDER_DATE, ORDER_ID;

